/**
 * shell-icon-assets.ts — Embedded PNG art for system-app icons.
 *
 * Base64-encoded PNGs (downscaled to 256x256, alpha preserved) for system apps
 * that use real artwork instead of the procedural `shell-icons.ts` silhouettes.
 * Embedded as data-URL strings so they survive the `tsc` build and the symlinked
 * dist with no asset-copying step. Consumed via the same image -> rgba ->
 * Billboard3D path as the host logo (see shell-ui-manager `setBillboardFromImage`).
 *
 * Source art lives in the user's Downloads (pencil/gear/install .png); regenerate
 * by re-running the downscale+base64 encode on the source PNGs.
 */
export const SHELL_ICON_PENCIL =
  'data:image/png;base64,';

export const SHELL_ICON_GEAR =
  'data:image/png;base64,';

export const SHELL_ICON_INSTALL =
  'data:image/png;base64,';
